import { useRef, useState, type ChangeEvent, type KeyboardEvent } from 'react';
import { Stack, Input, Tag, Button } from '@jinx-ui/react';

export interface ArticleTagPickerProps {
  label?: string;
  placeholder?: string;
  defaultValue?: string[];
  onChange?: (tags: string[]) => void;
}

const normalize = (raw: string) => raw.trim().replace(/\s+/g, ' ');

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultValue = [],
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(defaultValue);
  const [draft, setDraft] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);

  const apply = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const commit = (candidates: string[]) => {
    const next = [...tags];
    for (const candidate of candidates) {
      const tag = normalize(candidate);
      if (tag && !next.some((existing) => existing.toLowerCase() === tag.toLowerCase())) {
        next.push(tag);
      }
    }
    if (next.length !== tags.length) apply(next);
  };

  const remove = (tag: string) => {
    apply(tags.filter((existing) => existing !== tag));
    inputRef.current?.focus();
  };

  const handleChange = (event: ChangeEvent<HTMLInputElement>) => {
    const raw = event.target.value;
    if (raw.includes(',')) {
      const parts = raw.split(',');
      commit(parts.slice(0, -1));
      setDraft(parts[parts.length - 1]);
      return;
    }
    setDraft(raw);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      commit([draft]);
      setDraft('');
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      remove(tags[tags.length - 1]);
    }
  };

  return (
    <Stack gap="sm">
      <Input
        ref={inputRef}
        label={label}
        placeholder={placeholder}
        value={draft}
        onChange={handleChange}
        onKeyDown={handleKeyDown}
        onBlur={() => {
          commit([draft]);
          setDraft('');
        }}
        aria-describedby="article-tag-picker-list"
      />

      {tags.length > 0 && (
        <Stack
          id="article-tag-picker-list"
          direction="row"
          wrap
          gap="xs"
          role="list"
          style={{ rowGap: 'var(--jx-space-2)' }}
        >
          {tags.map((tag) => (
            <Tag key={tag} role="listitem">
              {tag}
              <Button
                variant="ghost"
                size="xs"
                aria-label={`Удалить тег ${tag}`}
                onClick={() => remove(tag)}
              >
                ×
              </Button>
            </Tag>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

